using ModelContextProtocol;
using PowerShapeMcp;
using Xunit;
namespace PowerShapeMcp.Tests;
public sealed class ReturnedSetObservationTests
{
 [Fact]public void PublicSchemaAcceptsAllThreeArtifactHashes(){var f=Config();using var s=new BridgeSession(f.Options());var tool=Assert.Single(ReturnedSurfaceSetObservationTools.Create(s));var properties=tool.ProtocolTool.InputSchema.GetProperty("properties");foreach(string field in new[]{"executionReceiptSha256","executionPlanSha256","openVerificationReceiptSha256"}){string pattern=properties.GetProperty(field).GetProperty("pattern").GetString()!;Assert.Matches(pattern,new string('a',64));Assert.DoesNotMatch(pattern,new string('a',32));}}
 static Fixture Config(bool enabled=true){var f=new Fixture();foreach(var k in new[]{"ownedSurfaceSetRotationsExperimental","ownedOpenAccessRestoreExperimental","workingCopyOpenExperimental","ownedSurfaceRotationsExperimental","rotationPlansExperimental","ownedRotationPlansExperimental","ownedSurfaceSetTranslationsExperimental","ownedSurfaceTranslationsExperimental","surfaceSamplingExperimental","ownedTranslationsExperimental","ownedOperationPlansExperimental","operationPlansExperimental","entitySetsExperimental","workingCopiesExperimental","documentBindingsExperimental"})f.Config[k]=true;f.Config["returnedSurfaceSetObservationExperimental"]=enabled;f.SaveConfig();return f;}
 [Theory][InlineData(false,true,1)][InlineData(false,false,0)][InlineData(true,true,0)]public void FullOnlyNewGate(bool readOnly,bool enabled,int expected){var f=Config(enabled);using var s=new BridgeSession(f.Options(readOnly));Assert.Equal(expected,ToolCatalog.Create(s).Count(t=>t.ProtocolTool.Name.EndsWith("observe_returned_surface_set_rotation",StringComparison.Ordinal)));}
 [Theory][InlineData("ownedSurfaceSetTranslationsExperimental")][InlineData("ownedSurfaceRotationsExperimental")][InlineData("surfaceSamplingExperimental")]public void RequiresStrictDependencies(string dep){var f=Config();f.Config[dep]=false;f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
 [Fact]public void BooleanOnly(){var f=Config();f.Config["returnedSurfaceSetObservationExperimental"]=1;f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
 [Fact]public async Task UnknownOriginNoQueue(){var f=Config();using var s=new BridgeSession(f.Options());var r=await new ReturnedSurfaceSetObservationTools(s).Observe(new('a',32),new('b',64),new('c',64),new('d',32),new('e',64),new('f',32),new('1',32),CancellationToken.None);Assert.True(r.IsError);Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
 [Fact]public async Task ReadOnlyDirectRefusal(){var f=Config();using var s=new BridgeSession(f.Options(true));await Assert.ThrowsAsync<McpProtocolException>(()=>new ReturnedSurfaceSetObservationTools(s).Observe(new('a',32),new('b',64),new('c',64),new('d',32),new('e',64),new('f',32),new('1',32),CancellationToken.None));Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
}
